class Order(
    private val id: OrderId,
    private val creditLimitCents: Long,
) {
    val lines: List<OrderLine> field = mutableListOf()   // read-only outside, mutable inside
    var totalCents: Long = 0
        private set
    fun addLine(line: OrderLine) {
        require(totalCents + line.amountCents <= creditLimitCents) { "credit limit exceeded" }
        lines.add(line)
        totalCents += line.amountCents
    }
}
